(async () => {
  try {
    let organizationId = this.getVarGlobal("deptParentId");
    if (organizationId === "0") {
      organizationId = this.getVarSystem("deptIds").split(",")[0];
    }

    console.log("Organization ID:", organizationId);

    await this.setData({ organization_id: organizationId });

    const resPickingSetup = await db
      .collection("picking_setup")
      .where({ organization_id: organizationId })
      .get();

    if (!resPickingSetup || resPickingSetup.data.length === 0) {
      this.setData({
        picking_setup_id: "",
        movement_type: "",
        picking_required: 0,
        picking_after: "",
        auto_trigger_to: 0,
        is_loading_bay: 0,
        allow_full_picking: 0,
        picking_mode: "",
        default_strategy_id: "",
        fallback_strategy_id: "",
        auto_completed_gd: 0,
        auto_completed_si: 0,
        bin_validation_scope: "",
        require_bin_scan: 0,
        require_batch_scan: 0,
        require_item_scan: 0,
        require_hu_scan: 0,
        split_policy: "",
        full_cl_check: 0,
        convert_gd_created: 0,
        lot_picking_required: 0,
        pt_picking_required: 0,
        msi_picking_required: 0,
        sp_auto_advance: 0,
        sp_allow_full_picking: 0,
      });
      return;
    }

    this.setData({
      picking_setup_id: resPickingSetup.data[0].id,
      movement_type: resPickingSetup.data[0].movement_type,
      picking_required: resPickingSetup.data[0].picking_required,
      picking_after: resPickingSetup.data[0].picking_after,
      auto_trigger_to: resPickingSetup.data[0].auto_trigger_to,
      is_loading_bay: resPickingSetup.data[0].is_loading_bay,
      allow_full_picking: resPickingSetup.data[0].allow_full_picking,
      picking_mode: resPickingSetup.data[0].picking_mode,
      default_strategy_id: resPickingSetup.data[0].default_strategy_id,
      fallback_strategy_id: resPickingSetup.data[0].fallback_strategy_id,
      auto_completed_gd: resPickingSetup.data[0].auto_completed_gd,
      auto_completed_si: resPickingSetup.data[0].auto_completed_si,
      bin_validation_scope: resPickingSetup.data[0].bin_validation_scope,
      require_bin_scan: resPickingSetup.data[0].require_bin_scan,
      require_batch_scan: resPickingSetup.data[0].require_batch_scan,
      require_item_scan: resPickingSetup.data[0].require_item_scan,
      require_hu_scan: resPickingSetup.data[0].require_hu_scan,
      split_policy: resPickingSetup.data[0].split_policy,
      full_cl_check: resPickingSetup.data[0].full_cl_check || 0,
      convert_gd_created: resPickingSetup.data[0].convert_gd_created || 0,
      lot_picking_required: resPickingSetup.data[0].lot_picking_required || 0,
      pt_picking_required: resPickingSetup.data[0].pt_picking_required || 0,
      msi_picking_required: resPickingSetup.data[0].msi_picking_required || 0,
      sp_auto_advance: resPickingSetup.data[0].sp_auto_advance || 0,
      sp_allow_full_picking: resPickingSetup.data[0].sp_allow_full_picking || 0,
    });

    // Loading Bay staging needs the GD to pass through "Created" so the
    // Reserved allocation can be shuttled to the bay bin — Auto Complete GD
    // skips that state. Keep the two mutually exclusive on load as well as
    // onChange (see PickingSetupOnChangeLoadingBay.js).
    if (resPickingSetup.data[0].is_loading_bay === 1) {
      this.disabled(["auto_completed_gd"], true);
    }
  } catch (error) {
    console.error(error);
    this.$message.error(error.message || "An error occurred");
  }
})();

const closeDialog = () => {
  if (this.parentGenerateForm) {
    this.parentGenerateForm.$refs.SuPageDialogRef.hide();
    this.parentGenerateForm.refresh();
    this.hideLoading();
  }
};

(async () => {
  try {
    const data = this.getValues();
    const {
      picking_setup_id,
      movement_type,
      picking_required,
      picking_after,
      auto_trigger_to,
      is_loading_bay,
      allow_full_picking,
      picking_mode,
      default_strategy_id,
      fallback_strategy_id,
      auto_completed_gd,
      auto_completed_si,
      bin_validation_scope,
      require_bin_scan,
      require_batch_scan,
      require_item_scan,
      require_hu_scan,
      organization_id,
      split_policy,
      full_cl_check,
      convert_gd_created,
      lot_picking_required,
      pt_picking_required,
      msi_picking_required,
      sp_auto_advance,
      sp_allow_full_picking,
    } = data;

    // Loading Bay staging requires the GD to pass through "Created" so the
    // Reserved allocation can be shuttled from the source bin to the bay bin.
    // Auto Complete GD skips that state entirely, leaving the reservation
    // stranded at the source while the delivery reads from the bay.
    if (is_loading_bay === 1 && auto_completed_gd === 1) {
      this.$message.error(
        "Loading Bay cannot be used together with Auto Complete GD. " +
          "Turn off Auto Complete GD so the Goods Delivery passes through Created.",
      );
      return;
    }

    const entry = {
      movement_type,
      picking_required,
      picking_after,
      auto_trigger_to,
      is_loading_bay,
      allow_full_picking,
      picking_mode,
      default_strategy_id,
      fallback_strategy_id,
      auto_completed_gd,
      auto_completed_si,
      bin_validation_scope,
      require_bin_scan,
      require_batch_scan,
      require_item_scan,
      require_hu_scan,
      organization_id,
      split_policy,
      full_cl_check: full_cl_check || 0,
      convert_gd_created: convert_gd_created || 0,
      // Stock Picking: one master switch per issuing movement type, plus its two
      // behaviour flags. Kept as columns rather than extra rows because every
      // picking_setup reader filters on org/plant only and takes data[0].
      lot_picking_required: lot_picking_required || 0,
      pt_picking_required: pt_picking_required || 0,
      msi_picking_required: msi_picking_required || 0,
      sp_auto_advance: sp_auto_advance || 0,
      sp_allow_full_picking: sp_allow_full_picking || 0,
    };

    if (picking_setup_id !== "") {
      await db.collection("picking_setup").doc(picking_setup_id).update(entry);

      const plantList = await db
        .collection("blade_dept")
        .where({ parent_id: entry.organization_id })
        .get()
        .then((res) => {
          return res.data.map((item) => item.id);
        });

      if (plantList.length === 0) {
        // No plants exist, use organization_id as plant_id
        const pickingSetup = await db
          .collection("picking_setup")
          .where({
            plant_id: entry.organization_id,
            organization_id: entry.organization_id,
          })
          .get();
        if (pickingSetup.data.length > 0) {
          await db
            .collection("picking_setup")
            .doc(pickingSetup.data[0].id)
            .update(entry);
        } else {
          // Create new picking_setup for organization level
          await db.collection("picking_setup").add({
            ...entry,
            plant_id: entry.organization_id,
            organization_id: entry.organization_id,
          });
        }
      } else {
        // Plants exist, update or create for each plant
        for (const plant of plantList) {
          const pickingSetup = await db
            .collection("picking_setup")
            .where({ plant_id: plant, organization_id: entry.organization_id })
            .get();
          if (pickingSetup.data.length > 0) {
            await db
              .collection("picking_setup")
              .doc(pickingSetup.data[0].id)
              .update(entry);
          } else {
            // Create new picking_setup for this plant
            await db.collection("picking_setup").add({
              ...entry,
              plant_id: plant,
              organization_id: entry.organization_id,
            });
          }
        }
      }
    } else {
      await db.collection("picking_setup").add(entry);

      const plantList = await db
        .collection("blade_dept")
        .where({ parent_id: entry.organization_id })
        .get()
        .then((res) => {
          return res.data.map((item) => item.id);
        });

      if (plantList.length === 0) {
        // No plants exist, use organization_id as plant_id
        await db.collection("picking_setup").add({
          ...entry,
          plant_id: entry.organization_id,
          organization_id: entry.organization_id,
        });
      } else {
        // Plants exist, create for each plant
        for (const plant of plantList) {
          await db.collection("picking_setup").add({
            ...entry,
            plant_id: plant || entry.organization_id,
            organization_id: entry.organization_id,
          });
        }
      }
    }

    // Fix any existing records with null plant_id for this organization
    const allOrgRecords = await db
      .collection("picking_setup")
      .where({ organization_id: entry.organization_id })
      .get();

    for (const record of allOrgRecords.data) {
      if (
        record.plant_id === null ||
        record.plant_id === "" ||
        record.plant_id === undefined
      ) {
        await db
          .collection("picking_setup")
          .doc(record.id)
          .update({ plant_id: record.organization_id });
        console.log(`Fixed null plant_id for record ${record.id}`);
      }
    }

    closeDialog();
    this.$message.success("Update Successfully");
  } catch (error) {
    console.error(error);
    this.$message.error(error.message || "An error occurred");
  }
})();

(async () => {
  try {
    const pickingAfter = await this.getValue("picking_after");

    if (pickingAfter === "Goods Delivery") {
      await this.display([
        "auto_trigger_to",
        "auto_completed_gd",
        "allow_full_picking",
        "convert_gd_created",
      ]);
      this.disabled(["picking_required"], false);

      // display() above re-enables auto_completed_gd — re-apply the Loading Bay
      // lock so switching picking_after can't resurrect the invalid combination
      // (see PickingSetupOnChangeLoadingBay.js).
      if (this.getValue("is_loading_bay") === 1) {
        await this.setData({ auto_completed_gd: 0 });
        this.disabled(["auto_completed_gd"], true);
      }
    } else if (pickingAfter === "Sales Order") {
      await this.hide([
        "auto_trigger_to",
        "auto_completed_gd",
        "allow_full_picking",
        "convert_gd_created",
      ]);
      await this.setData({
        auto_trigger_to: 0,
        auto_completed_gd: 0,
        picking_required: 1,
        allow_full_picking: 0,
        convert_gd_created: 0,
      });
      this.disabled(["picking_required"], true);
    } else {
      await this.hide(["auto_trigger_to", "auto_completed_gd"]);
      await this.display(["convert_gd_created"]);
    }
  } catch (error) {
    console.error(error);
    this.$message.error(error.message || "An error occurred");
  }
})();

// Loading Bay staging and Auto Complete GD are mutually exclusive.
//
// With is_loading_bay = 1 the picker moves stock into a staging bin, and the
// Reserved allocation has to follow it. That shuttle (detectBinHuMigrations in
// GDProcessTable_batchProcess) only runs on a "Created" save, so the GD MUST
// pass through Created. auto_completed_gd = 1 sends picking straight to a
// "Completed" GD save, the shuttle never fires, and the delivery then tries to
// take unrestricted stock from a bay bin that was never stocked.
(async () => {
  try {
    const isLoadingBay = arguments[0].value;

    if (isLoadingBay === 1) {
      await this.setData({ auto_completed_gd: 0 });
      this.disabled(["auto_completed_gd"], true);
      return;
    }

    // Only re-enable where the field is meaningful — picking_after
    // "Sales Order" keeps it hidden and forced to 0 on its own.
    const pickingAfter = await this.getValue("picking_after");
    if (pickingAfter === "Goods Delivery") {
      this.disabled(["auto_completed_gd"], false);
    }
  } catch (error) {
    console.error(error);
    this.$message.error(error.message || "An error occurred");
  }
})();
